CREATE   PROCEDURE [synapse_ce].[usp_Insert_rics_question]
AS
BEGIN
	INSERT INTO [synapse_ce].[rics_question]
	(
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[rics_attachedto],
		[rics_fetchxmlexpression],
		[rics_helptext],
		[rics_memotext],
		[rics_name],
		[rics_questionid],
		[rics_questionsetid],
		[rics_questionsetid_entitytype],
		[rics_questionsetidname],
		[rics_questiontext],
		[rics_questiontitle],
		[rics_questiontype],
		[rics_raiseincident],
		[rics_replacesquestion],
		[rics_replacesquestion_entitytype],
		[rics_replacesquestionname],
		[rics_requiresevidence],
		[rics_requiresheadings],
		[rics_selectedconfirmationentity],
		[rics_selectedconfirmationfield],
		[rics_uploadhelptext],
		[rics_validfrom],
		[rics_validto],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[rics_attachedto],
		stg.[rics_fetchxmlexpression],
		stg.[rics_helptext],
		stg.[rics_memotext],
		stg.[rics_name],
		stg.[rics_questionid],
		stg.[rics_questionsetid],
		stg.[rics_questionsetid_entitytype],
		stg.[rics_questionsetidname],
		stg.[rics_questiontext],
		stg.[rics_questiontitle],
		stg.[rics_questiontype],
		stg.[rics_raiseincident],
		stg.[rics_replacesquestion],
		stg.[rics_replacesquestion_entitytype],
		stg.[rics_replacesquestionname],
		stg.[rics_requiresevidence],
		stg.[rics_requiresheadings],
		stg.[rics_selectedconfirmationentity],
		stg.[rics_selectedconfirmationfield],
		stg.[rics_uploadhelptext],
		stg.[rics_validfrom],
		stg.[rics_validto],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[rics_question] stg
		LEFT JOIN [synapse_ce].[rics_question] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
